        base = Decimal("12.00")
    elif peso_kg <= 5:
        fracoes = math.ceil(peso_kg - 1)
        base = Decimal("12.00") + Decimal(fracoes) * Decimal("3.50")
    else:
        fracoes = math.ceil(peso_kg - 5)
        base = Decimal("26.00") + Decimal(fracoes) * Decimal("2.80")

    # 3. Multiplicador regional
